import { DISTRICT_MAP } from "./districtMap";

/**
 * Mainland Portugal by district, faint, as the home page hero's background: a hint that every
 * answer comes from the Portuguese market. Decorative only. Boundaries from CAOP 2025 (DGT,
 * CC BY 4.0), generated by scripts/district-map.mjs.
 */
export function DistrictMap({ className }: { className?: string }) {
  return (
    <svg
      viewBox={`0 0 ${DISTRICT_MAP.width} ${DISTRICT_MAP.height}`}
      aria-hidden
      focusable="false"
      className={className}
    >
      <g
        className="fill-primary/[0.06] stroke-primary/40"
        strokeWidth="0.7"
        strokeLinejoin="round"
        vectorEffect="non-scaling-stroke"
      >
        {DISTRICT_MAP.districts.map((d) => (
          <path key={d.code} d={d.d} vectorEffect="non-scaling-stroke" />
        ))}
      </g>
    </svg>
  );
}
